private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int n = i;
    while (bb.hasRemaining()) {
        int b = bb.get();
        if (b >= 0 && b <= 0x7F) {
            sb.append((char) b);
            n++;
        } else if (b >= 0xC0 && b <= 0xDF) {
            b &= 0x1F;
            int b2 = bb.get();
            if (b2 >= 0x80 && b2 <= 0xBF) {
                sb.append((char) ((b << 6) + b2));
                n += 2;
            } else {
                throw new IllegalArgumentException("Invalid UTF-8 encoding");
            }
        } else if (b >= 0xE0 && b <= 0xEF) {
            b &= 0x0F;
            int b2 = bb.get();
            int b3 = bb.get();
            if (b2 >= 0x80 && b2 <= 0xBF && b3 >= 0x80 && b3 <= 0xBF) {
                sb.append((char) ((b << 12) + (b2 << 6) + b3));
                n += 3;
            } else {
                throw new IllegalArgumentException("Invalid UTF-8 encoding");
            }
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 encoding");
        }
    }
    return n;
}

